const response = $input.item.json.response;

if (!response || !response.data || response.data.length === 0) {
  return [{ json: $input.item.json }];
}

const sampleRecords = response.data.slice(0, 5);
const firstRecord = sampleRecords[0];
const fieldNames = Object.keys(firstRecord);

const enrichedSchema = fieldNames.map(fieldName => {
  const examples = sampleRecords
    .map(record => record[fieldName])
    .filter(val => val != null && val !== '');

  const sampleValue = examples[0];
  let type = 'string';
  if (typeof sampleValue === 'number') type = Number.isInteger(sampleValue) ? 'integer' : 'decimal';
  if (typeof sampleValue === 'boolean') type = 'boolean';
  if (fieldName.toLowerCase().includes('email')) type = 'email';
  if (fieldName.toLowerCase().includes('date') || fieldName.toLowerCase().includes('time')) type = 'datetime';
  if (fieldName.toLowerCase().includes('id')) type = 'uuid';

  return {
    name: fieldName,
    type: type,
    description: `Auto-generated field: ${fieldName}`,
    examples: examples.slice(0, 5)
  };
});

const domainName = (response.message || 'auto_domain')
  .replace(/[^a-zA-Z0-9\s-]/g, '')
  .trim()
  .substring(0, 50) || `auto_${Date.now()}`;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5678/webhook/manage-domain-with-registry',
    json: true,
    body: {
      domain: domainName,
      schema: enrichedSchema,
      action: 'create',
      description: `Auto-generated domain`,
      category: 'Auto-Generated'
    },
    timeout: 5000
  });
  console.log('Stored:', domainName);
} catch (error) {
  console.log('Skip:', error.message);
}

return [{ json: $input.item.json }];

