// ========================================
// DATA GENERATOR (RAG) - ROBUST & GENERIC
// ========================================

const buildMessage = $('Build Enhanced System Message').item.json;
const parserOutput = $input.item.json;

const parsedResponse = parserOutput.parsedResponse || parserOutput;

let schema, recordCount, message;

if (buildMessage.isSchemaProvided && buildMessage.providedSchema) {
  schema = buildMessage.providedSchema;
  recordCount = buildMessage.recordCount || 100;
  message = 'Generating data using provided schema';
} else {
  schema = parsedResponse.schema || [];
  recordCount = parsedResponse.recordCount || 100;
  message = parsedResponse.message || '';
}

const sampleData = parserOutput.sampleData || parsedResponse.sampleData;

let fieldPatterns = {};

if (sampleData && Array.isArray(sampleData) && sampleData.length > 0) {
  sampleData.forEach(record => {
    Object.keys(record).forEach(fieldName => {
      const value = record[fieldName];
      if (value === null || value === undefined) return;
      if (!fieldPatterns[fieldName]) fieldPatterns[fieldName] = [];
      if (typeof value === 'string' && value.trim().length > 0) {
        const trimmedValue = value.trim();
        if (!fieldPatterns[fieldName].includes(trimmedValue)) fieldPatterns[fieldName].push(trimmedValue);
      } else if (typeof value === 'number' && !isNaN(value)) {
        if (!fieldPatterns[fieldName].includes(value)) fieldPatterns[fieldName].push(value);
      } else if (typeof value === 'boolean') {
        if (!fieldPatterns[fieldName].includes(value)) fieldPatterns[fieldName].push(value);
      } else if (typeof value === 'object' && value !== null) {
        fieldPatterns[fieldName].push(JSON.parse(JSON.stringify(value)));
      }
    });
  });
}

function deepCopyIfObject(v) { return (typeof v === 'object' && v !== null) ? JSON.parse(JSON.stringify(v)) : v; }
function getPatternValue(fieldName) {
  if (!fieldPatterns || Object.keys(fieldPatterns).length === 0) return null;
  const fieldNameLower = fieldName.toLowerCase();
  if (fieldPatterns[fieldName] && fieldPatterns[fieldName].length > 0) {
    const v = fieldPatterns[fieldName][Math.floor(Math.random() * fieldPatterns[fieldName].length)];
    return deepCopyIfObject(v);
  }
  for (const patternFieldName in fieldPatterns) {
    if (patternFieldName.toLowerCase() === fieldNameLower) {
      const values = fieldPatterns[patternFieldName];
      if (values && values.length > 0) { const v = values[Math.floor(Math.random() * values.length)]; return deepCopyIfObject(v); }
    }
  }
  for (const patternFieldName in fieldPatterns) {
    const patternFieldNameLower = patternFieldName.toLowerCase();
    if (fieldNameLower.includes(patternFieldNameLower) && patternFieldNameLower.length > 3) {
      const values = fieldPatterns[patternFieldName];
      if (values && values.length > 0) { const v = values[Math.floor(Math.random() * values.length)]; return deepCopyIfObject(v); }
    }
  }
  return null;
}

function generateByType(fieldType) {
  const typeLower = (fieldType || 'string').toLowerCase();
  if (typeLower.includes('int')) return Math.floor(Math.random() * 10000) + 1;
  if (typeLower.includes('dec') || typeLower.includes('float') || typeLower.includes('num')) return parseFloat((Math.random() * 1000).toFixed(2));
  if (typeLower.includes('bool')) return Math.random() > 0.5;
  if (typeLower.includes('date')) return new Date().toISOString().split('T')[0];
  if (typeLower.includes('uuid')) return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => (c === 'x' ? Math.random() * 16 | 0 : (Math.random() * 16 | 0) & 0x3 | 0x8).toString(16));
  if (typeLower.includes('email')) return `user${Math.floor(Math.random() * 10000)}@example.com`;
  if (typeLower === 'object' || typeLower.includes('object')) {
    const r = () => Math.random().toString(36).slice(2, 10);
    return { name: r(), city: r(), country: r(), address: r() };
  }
  if (typeLower === 'array' || typeLower.includes('array')) {
    const len = 2 + Math.floor(Math.random() * 4);
    return Array.from({ length: len }, (_, i) => 'Item ' + (i + 1));
  }
  return `sample_${typeLower}_value`;
}

function generateValue(fieldName, fieldType) {
  const patternValue = getPatternValue(fieldName);
  if (patternValue !== null) return patternValue;
  return generateByType(fieldType);
}

let data = [];
const previewCount = Math.min(10, recordCount);

if (schema.length === 0 && sampleData && sampleData.length > 0) {
  const firstRecord = sampleData[0];
  schema = Object.keys(firstRecord).map(fieldName => {
    const value = firstRecord[fieldName];
    let fieldType = 'string';
    if (typeof value === 'number') fieldType = Number.isInteger(value) ? 'int' : 'decimal';
    else if (typeof value === 'boolean') fieldType = 'boolean';
    return { name: fieldName, type: fieldType };
  });
}

if (schema.length > 0) {
  for (let i = 0; i < previewCount; i++) {
    const record = {};
    schema.forEach(field => {
      record[field.name] = generateValue(field.name, field.type);
    });
    data.push(record);
  }
}

const successMessage = sampleData && sampleData.length > 0
  ? message || 'Data generated using AI-provided patterns'
  : message || 'Data generated using type-based generators';

return [{
  json: {
    response: {
      message: successMessage,
      schema: schema,
      data: data,
      recordCount: recordCount,
      rag_enhanced: buildMessage.retrievedExamples > 0,
      fieldPatterns: fieldPatterns
    }
  }
}];

