// Build enhanced system message with retrieved examples
const searchResults = $input.item.json.result || [];
const webhookData = $('Webhook Trigger').item.json;

if (webhookData.body && webhookData.body.schema && Array.isArray(webhookData.body.schema) && webhookData.body.schema.length > 0) {
  return [{
    json: {
      systemMessage: "Use the provided schema to generate data. Do not modify the schema.",
      providedSchema: webhookData.body.schema,
      recordCount: webhookData.body.recordCount || 100,
      isSchemaProvided: true,
      webhookData: webhookData.body
    }
  }];
}

let enhancedSystemMessage = `You are a specialized synthetic data generator assistant. Your ONLY purpose is to help users generate test/dummy/sample data.

YOUR ROLE:
- Generate synthetic data for ANY use case requested by users
- Accept all requests related to data generation
- ONLY decline if asked completely unrelated questions

YOUR PROCESS:
1. UNDERSTAND: Read the request and conversational context
2. EXTRACT: Identify dataset type, fields, rules
3. DESIGN: Create schema with appropriate field names/types
4. RESPOND: Provide the JSON schema format

IMPORTANT RULES:
- MAXIMUM 1,000 records per request
- Default to 100 records if not specified
- Be creative with field types

RESPONSE FORMAT (JSON only - CRITICAL: Must be a SINGLE VALID JSON object):
{
  "message": "Brief explanation of what you're generating",
  "schema": [
    {"name": "descriptive_field_name", "type": "appropriate_type"},
    ...
  ],
  "recordCount": number,
  "sampleData": [
    {"field1": "value1", "field2": "value2", ...},
    ... (at least 10 sample records)
  ]
}

CRITICAL JSON RULES:
- Output ONLY valid JSON. Start with { and end with }
- NO markdown blocks (no \`\`\`json)
- NO conversational text before or after the JSON
- All strings must be properly quoted

`;

if (searchResults.length > 0) {
  enhancedSystemMessage += "\n\nRELEVANT EXAMPLES (Use as inspiration):\n";
  searchResults.forEach((result, index) => {
    const payload = result.payload;
    enhancedSystemMessage += `Example ${index + 1}:\n${JSON.stringify(payload.schema, null, 2)}\n\n`;
  });
}

enhancedSystemMessage += `EXAMPLES OF CORRECT OUTPUT FORMAT:

{
  "message": "Generating credit card transaction records.",
  "schema": [
    {"name": "transaction_id", "type": "transactionId"},
    {"name": "amount", "type": "transactionAmount"},
    {"name": "status", "type": "paymentStatus"}
  ],
  "recordCount": 100,
  "sampleData": [
    {"transaction_id": "TXN001", "amount": 99.99, "status": "completed"},
    {"transaction_id": "TXN002", "amount": 45.50, "status": "pending"}
  ]
}

{
  "message": "Creating loyalty program member records.",
  "schema": [
    {"name": "member_id", "type": "uuid"},
    {"name": "email", "type": "email"},
    {"name": "tier", "type": "membershipTier"}
  ],
  "recordCount": 100,
  "sampleData": [
    {"member_id": "550e8400-e29b", "email": "alice@example.com", "tier": "Gold"},
    {"member_id": "6ba7b810-9dad", "email": "bob@example.com", "tier": "Silver"}
  ]
}
`;

return [{
  json: {
    systemMessage: enhancedSystemMessage,
    retrievedExamples: searchResults.length,
    webhookData: webhookData.body
  }
}];

// RESPONSE PARSER - Extract JSON from AI output (string or object).
const raw = $input.first().json;
const rawOutput = (raw && typeof raw === 'object' && (raw.output !== undefined ? raw.output : raw.text || raw.message)) || (typeof raw === 'string' ? raw : '');
const rawStr = typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput || '');

let finalObject = {};
let sampleData = [];

// 1) Try direct parse (output is often a JSON string)
try {
  finalObject = JSON.parse(rawStr);
  if (finalObject && typeof finalObject === 'object') {
    sampleData = Array.isArray(finalObject.sampleData) ? finalObject.sampleData : [];
  }
} catch (e) {
  // 2) Brace-count: find first { and matching }
  let start = rawStr.indexOf('{');
  if (start !== -1) {
    let depth = 0;
    let end = -1;
    for (let i = start; i < rawStr.length; i++) {
      if (rawStr[i] === '{') depth++;
      else if (rawStr[i] === '}') { depth--; if (depth === 0) { end = i; break; } }
    }
    if (end !== -1) {
      try {
        finalObject = JSON.parse(rawStr.substring(start, end + 1));
        sampleData = Array.isArray(finalObject.sampleData) ? finalObject.sampleData : [];
      } catch (e2) {}
    }
  }
}

if (!Array.isArray(finalObject.schema)) finalObject.schema = [];
if (typeof finalObject.recordCount !== 'number') finalObject.recordCount = 100;
if (!Array.isArray(sampleData)) sampleData = finalObject.sampleData || [];

return [{
  json: {
    parsedResponse: finalObject,
    sampleData: sampleData
  }
}];
